live_write.source:
live fn C() { pub let mut n = 1 }
let mut c = C()
act fn main() { c.n = 2 }

live_private.source:
live fn C() { let n = 1 }
let c = C()
act fn main() { let x = c.n; let done = 0 }

live_function_value.source:
live fn C() { pub fn get() -> Int { 1 } }
let c = C()
fn main() { let f = snap(c).get; let done = 0 }

live_watch.source:
import io { println }
live fn C() { pub let n = 1 }
let c = C()
watch { println("{c.n}") }

live_emit_index.source:
live fn C() { pub event Tick }
let cs = [C()]
act fn main() { emit cs[0].Tick() }

live_template_cross.source:
live fn C() { pub derived d: Int = total + 1 }
let c = C()
derived total: Int = c.d

live_hold_cycle.source:
live fn C() { pub let mut children: [C] = []; pub event Adopt(x: C); on Adopt(x) { children.push(x) } }
let c = C()
act fn main() { emit c.Adopt(c) }

live_dynamic_cycle.source:
live fn C() { pub let mut children: [C] = []; pub derived size: Int = 1 + children.map(|c| c.size).reduce(0, |a, b| a + b); pub event Adopt(x: C); on Adopt(x) { children.push(x) } }
let c = C()
act fn main() { emit c.Adopt(c) }

live_fixed_param.source:
import io { println }
live fn C(x: Int) { pub fn get() -> Int { x }; pub act fn reset() { x = 2 } }
let mut c = C(1)
act fn main() { c.reset(); println("{c.get()}") }

live_plain_read.source:
live fn C() { pub let n = 1 }
let c = C()
fn f(c: C) -> Int { c.n }
fn main() -> Int { f(snap(c)) }

function_display.source:
import io { println }
fn id(x: Int) -> Int { x }
fn main() { println("{id}") }

trait_mismatch.source:
