let c = C()
act fn main() { c.n = 2 }

loop_tracked.source:
import io { println }
let mut x = 2
track fn sum() -> Int { let mut n = 0; for k in [x, x] { n += k }; n }
derived y = sum()
act fn main() { x = 3; println("{y}") }

ignore_effect.source:
import io { println }
fn noisy() -> Int { println("x"); 1 }
fn ignore(f: fn() -> Int) -> Int { 1 }
derived x = ignore(noisy)

live_dynamic_read_cycle.source:
live fn C() { pub derived d: Int = 1 + others.map(|c| c.d).reduce(0, |a, b| a + b) }
let mut others: [C] = []
let first = C()
act fn main() { others = [first] }

live_uninit.source:
live fn C() { pub derived d: Int = total + 1 }
let all = [C()]
fn sum(xs: [C]) -> Int { xs.map(|c| c.d).reduce(0, |a, b| a + b) }
derived total: Int = sum(all)
fn main() { }

live_alias.source:
